DO $test$
DECLARE sid uuid; e jsonb; batch jsonb; count_before integer;
BEGIN
 INSERT INTO master_wok_event_test.streams(service_date) VALUES('2026-10-17') RETURNING id INTO sid;
 e:=$events$[{"eventId": "event-1", "at": "2026-10-16T12:00:00Z", "kind": "RESERVATION_SET", "commitment": "PROPOSED", "order": {"orderId": "synthetic-a", "orderType": "collection", "targetAt": "2026-10-17T17:00:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-2", "at": "2026-10-17T15:00:00Z", "kind": "BOOKING_DECISION", "actualDecision": "ACCEPTED", "order": {"orderId": "synthetic-b", "orderType": "collection", "targetAt": "2026-10-17T18:00:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-3", "at": "2026-10-17T15:05:00Z", "kind": "RESERVATION_SET", "commitment": "CONFIRMED", "order": {"orderId": "synthetic-a", "orderType": "collection", "targetAt": "2026-10-17T18:20:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-4", "at": "2026-10-17T15:10:00Z", "kind": "BOOKING_DECISION", "actualDecision": "DECLINED", "order": {"orderId": "synthetic-c", "orderType": "collection", "targetAt": "2026-10-17T18:10:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-5", "at": "2026-10-17T15:15:00Z", "kind": "BOOKING_DECISION", "actualDecision": "ACCEPTED", "order": {"orderId": "synthetic-d", "orderType": "delivery", "targetAt": "2026-10-17T18:30:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-6", "at": "2026-10-17T15:20:00Z", "kind": "RESERVATION_RELEASED", "orderId": "synthetic-d", "reason": "CANCELLED"}, {"eventId": "event-7", "at": "2026-10-17T15:25:00Z", "kind": "BOOKING_DECISION", "actualDecision": "SUGGESTED", "order": {"orderId": "synthetic-e", "orderType": "collection", "targetAt": "2026-10-17T18:30:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-8", "at": "2026-10-17T15:30:00Z", "kind": "BOOKING_DECISION", "actualDecision": "ACCEPTED", "order": {"orderId": "synthetic-f", "orderType": "collection", "targetAt": "2026-10-17T19:00:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-9", "at": "2026-10-17T16:00:00Z", "kind": "RESERVATION_SET", "commitment": "PROPOSED", "order": {"orderId": "synthetic-a", "orderType": "collection", "targetAt": "2026-10-17T19:00:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-10", "at": "2026-10-17T16:01:00Z", "kind": "RESERVATION_SET", "commitment": "PROPOSED", "order": {"orderId": "synthetic-a", "orderType": "collection", "targetAt": "2026-10-17T19:30:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-11", "at": "2026-10-17T16:02:00Z", "kind": "PROPOSAL_RESPONSE", "orderId": "synthetic-a", "proposalEventId": "event-10", "response": "ACCEPTED"}, {"eventId": "event-12", "at": "2026-10-17T16:03:00Z", "kind": "RESERVATION_SET", "commitment": "PROPOSED", "order": {"orderId": "synthetic-a", "orderType": "collection", "targetAt": "2026-10-17T19:40:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-13", "at": "2026-10-17T16:04:00Z", "kind": "PROPOSAL_RESPONSE", "orderId": "synthetic-a", "proposalEventId": "event-12", "response": "REJECTED"}, {"eventId": "event-14", "at": "2026-10-17T16:05:00Z", "kind": "BOOKING_DECISION", "actualDecision": "DECLINED", "order": {"orderId": "synthetic-last", "orderType": "collection", "targetAt": "2026-10-17T17:00:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}]$events$::jsonb->0;
 BEGIN
  PERFORM master_wok_event_test.record(sid,e);
  RAISE EXCEPTION 'TEST_DISABLED_FAILED';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'SOURCE_DISABLED' THEN RAISE; END IF; END;
 UPDATE master_wok_event_test.streams SET enabled=true WHERE id=sid;
 FOR e IN SELECT value FROM jsonb_array_elements($events$[{"eventId": "event-1", "at": "2026-10-16T12:00:00Z", "kind": "RESERVATION_SET", "commitment": "PROPOSED", "order": {"orderId": "synthetic-a", "orderType": "collection", "targetAt": "2026-10-17T17:00:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-2", "at": "2026-10-17T15:00:00Z", "kind": "BOOKING_DECISION", "actualDecision": "ACCEPTED", "order": {"orderId": "synthetic-b", "orderType": "collection", "targetAt": "2026-10-17T18:00:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-3", "at": "2026-10-17T15:05:00Z", "kind": "RESERVATION_SET", "commitment": "CONFIRMED", "order": {"orderId": "synthetic-a", "orderType": "collection", "targetAt": "2026-10-17T18:20:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-4", "at": "2026-10-17T15:10:00Z", "kind": "BOOKING_DECISION", "actualDecision": "DECLINED", "order": {"orderId": "synthetic-c", "orderType": "collection", "targetAt": "2026-10-17T18:10:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-5", "at": "2026-10-17T15:15:00Z", "kind": "BOOKING_DECISION", "actualDecision": "ACCEPTED", "order": {"orderId": "synthetic-d", "orderType": "delivery", "targetAt": "2026-10-17T18:30:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-6", "at": "2026-10-17T15:20:00Z", "kind": "RESERVATION_RELEASED", "orderId": "synthetic-d", "reason": "CANCELLED"}, {"eventId": "event-7", "at": "2026-10-17T15:25:00Z", "kind": "BOOKING_DECISION", "actualDecision": "SUGGESTED", "order": {"orderId": "synthetic-e", "orderType": "collection", "targetAt": "2026-10-17T18:30:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-8", "at": "2026-10-17T15:30:00Z", "kind": "BOOKING_DECISION", "actualDecision": "ACCEPTED", "order": {"orderId": "synthetic-f", "orderType": "collection", "targetAt": "2026-10-17T19:00:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-9", "at": "2026-10-17T16:00:00Z", "kind": "RESERVATION_SET", "commitment": "PROPOSED", "order": {"orderId": "synthetic-a", "orderType": "collection", "targetAt": "2026-10-17T19:00:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-10", "at": "2026-10-17T16:01:00Z", "kind": "RESERVATION_SET", "commitment": "PROPOSED", "order": {"orderId": "synthetic-a", "orderType": "collection", "targetAt": "2026-10-17T19:30:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-11", "at": "2026-10-17T16:02:00Z", "kind": "PROPOSAL_RESPONSE", "orderId": "synthetic-a", "proposalEventId": "event-10", "response": "ACCEPTED"}, {"eventId": "event-12", "at": "2026-10-17T16:03:00Z", "kind": "RESERVATION_SET", "commitment": "PROPOSED", "order": {"orderId": "synthetic-a", "orderType": "collection", "targetAt": "2026-10-17T19:40:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}, {"eventId": "event-13", "at": "2026-10-17T16:04:00Z", "kind": "PROPOSAL_RESPONSE", "orderId": "synthetic-a", "proposalEventId": "event-12", "response": "REJECTED"}, {"eventId": "event-14", "at": "2026-10-17T16:05:00Z", "kind": "BOOKING_DECISION", "actualDecision": "DECLINED", "order": {"orderId": "synthetic-last", "orderType": "collection", "targetAt": "2026-10-17T17:00:00Z", "lines": [{"itemId": "panang-curry", "qty": 1, "mods": [{"id": "chicken"}]}], "deliveryReadyEstimate": null}}]$events$::jsonb) LOOP
  IF e->>'eventId'='event-11' THEN
   -- Earlier proposal cannot win against the replacement.
   BEGIN
    PERFORM master_wok_event_test.record(sid,e||'{"eventId":"stale","proposalEventId":"event-9"}'::jsonb);
    RAISE EXCEPTION 'TEST_STALE_FAILED';
   EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'STALE_PROPOSAL_RESPONSE' THEN RAISE; END IF; END;
   -- Force a surrounding transaction failure after a successful state/outbox write.
   BEGIN
    PERFORM master_wok_event_test.record(sid,e);
    RAISE EXCEPTION 'FORCED_ROLLBACK';
   EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'FORCED_ROLLBACK' THEN RAISE; END IF; END;
   IF (SELECT event_count FROM master_wok_event_test.streams WHERE id=sid)<>10 OR
      (SELECT commitment FROM master_wok_event_test.reservations WHERE stream_id=sid AND order_id='synthetic-a')<>'PROPOSED' THEN RAISE EXCEPTION 'TEST_ROLLBACK_FAILED'; END IF;
  END IF;
  IF master_wok_event_test.record(sid,e)<>'RECORDED' THEN RAISE EXCEPTION 'TEST_APPEND_FAILED'; END IF;
  IF master_wok_event_test.record(sid,e)<>'ALREADY_RECORDED' THEN RAISE EXCEPTION 'TEST_DUPLICATE_FAILED'; END IF;
 END LOOP;
 IF EXISTS(SELECT FROM master_wok_event_test.reservations WHERE stream_id=sid AND order_id='synthetic-a') THEN RAISE EXCEPTION 'TEST_REJECTION_RELEASE_FAILED'; END IF;
 batch:=master_wok_event_test.export(sid);
 IF jsonb_array_length(batch->'events')<>14 OR (batch->'coverage'->>'eventCount')::int<>14 THEN RAISE EXCEPTION 'TEST_EXPORT_FAILED'; END IF;
 BEGIN
  PERFORM master_wok_event_test.record(sid,jsonb_set(e,'{order,privateAddress}','"PRIVATE"'::jsonb)||'{"eventId":"private"}'::jsonb);
  RAISE EXCEPTION 'TEST_PRIVATE_FAILED';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'ORDER_REQUIRED' THEN RAISE; END IF; END;
 UPDATE master_wok_event_test.streams SET enabled=false WHERE id=sid;
END $test$;
SELECT id,event_count,enabled,master_wok_event_test.export(id) AS replay_export FROM master_wok_event_test.streams WHERE event_count=14 ORDER BY id;
